#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/pingcap-pd-v8.5.8-arm64-oci ] || "$F" docker.io/pingcap/pd sha256:864318d318b7baee87e4e711f5abad7cd09ca3827fdf0011d5ec6f68b714c9c7 pingcap/pd:v8.5.8 images/pingcap-pd-v8.5.8-arm64-oci
[ "$A" = arm64 ] || [ -f images/pingcap-pd-v8.5.8-amd64.docker.tar ] || "$F" docker.io/pingcap/pd sha256:507b401ece53aba15db9628a90a1e350c3cd1b9b39c086c708e2e88541b0e7fd pingcap/pd:v8.5.8 images/pingcap-pd-v8.5.8-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/pingcap-tikv-v8.5.8-arm64-oci ] || "$F" docker.io/pingcap/tikv sha256:60d7cbe7c4a1e91c9ddb38a0e7fc052ae4a172bfb80525c17dc589cf842f0f7a pingcap/tikv:v8.5.8 images/pingcap-tikv-v8.5.8-arm64-oci
[ "$A" = arm64 ] || [ -f images/pingcap-tikv-v8.5.8-amd64.docker.tar ] || "$F" docker.io/pingcap/tikv sha256:cdb681d570c490424d69ecc1ecda6865999f2b86ae3b2d2cb070989bf4d2701d pingcap/tikv:v8.5.8 images/pingcap-tikv-v8.5.8-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/pingcap-pd-v8.5.8-amd64.docker.tar images/pingcap-tikv-v8.5.8-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/pingcap-pd-v8.5.8-arm64-oci images/pingcap-tikv-v8.5.8-arm64-oci
